    % Circuit
    \draw (0,8.5) to[battery1, l=12 V] (0,6);
    \draw (0,8.5) to[R, l=$3\,\Omega$] (2,8.5)
      to[R, l=$2\,\Omega$] (4,8.5)
      to[R, l=$1\,\Omega$] (6,8.5);
    \draw (6,8.5) to[short] (6,6) -- (0,6);
    \node[ground, scale=0.8] at (6,6) {};
    \node[right] at (6.3,6) {$B$};
    \node[below] at (2,8.35) {$P$};
    \node[below] at (4,8.35) {$Q$};

    % Alignment guides: battery and resistor body edges only
    \draw[densely dotted, gray] (0,5.65) -- (0,3.35);
    \draw[densely dotted, gray] (0.6,8.15) -- (0.6,3.35);
    \draw[densely dotted, gray] (1.4,8.15) -- (1.4,3.35);
    \draw[densely dotted, gray] (2.6,8.15) -- (2.6,3.35);
    \draw[densely dotted, gray] (3.4,8.15) -- (3.4,3.35);
